/* ---- seed.js ---- */
// Seeded PRNG — mulberry32 + xmur3 (same algo as layover, extracted for reuse).
function xmur3(str) {
  let h = 1779033703 ^ str.length;
  for (let i = 0; i < str.length; i++) {
    h = Math.imul(h ^ str.charCodeAt(i), 3432918353);
    h = (h << 13) | (h >>> 19);
  }
  return function () {
    h = Math.imul(h ^ (h >>> 16), 2246822507);
    h = Math.imul(h ^ (h >>> 13), 3266489909);
    return (h ^= h >>> 16) >>> 0;
  };
}

function mulberry32(a) {
  return function () {
    let t = (a += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function seededRng(seedStr) {
  const seedFn = xmur3(seedStr);
  return mulberry32(seedFn());
}

function seededInt(rng, min, max) {
  return Math.floor(rng() * (max - min + 1)) + min;
}

function seededPick(rng, arr) {
  return arr[Math.floor(rng() * arr.length)];
}

// Week seed: everyone on Week N shares the same universe.
function weekSeed(weekNum) {
  return `CA-WEEK-${weekNum}`;
}

function weekRng(weekNum, namespace) {
  return seededRng(`${weekSeed(weekNum)}:${namespace}`);
}

/* ---- time.js ---- */
// Week clock. Internal unit = absolute minutes since Week start (Mon 00:00 UTC).
// Display converts to airport-local standard time via tzOffsetStd (no DST ever).


const WEEK_MINUTES = 7 * 1440;
const WEEK_START_HOUR_LOCAL = 6; // campaigns start Mon 06:00 at the starting airport

function weekStartAbs() {
  return 0;
}

function weekEndAbs() {
  return WEEK_MINUTES;
}

function isWeekOver(gameTime) {
  return gameTime >= WEEK_MINUTES;
}

// UTC minutes -> airport-local wall minutes (STD offset applied, wrapped to day).
function toLocalMinutes(absMinutes, airportId) {
  const ap = getAirportById(airportId);
  const off = ap ? ap.tzOffsetStd : 0;
  return absMinutes + off;
}

function formatLocalTime(absMinutes, airportId) {
  const ap = getAirportById(airportId);
  const local = toLocalMinutes(absMinutes, airportId);
  const minsInDay = ((local % 1440) + 1440) % 1440;
  let h = Math.floor(minsInDay / 60);
  const m = minsInDay % 60;
  const ampm = h >= 12 ? 'PM' : 'AM';
  const dh = h === 0 ? 12 : h > 12 ? h - 12 : h;
  return `${dh}:${String(m).padStart(2, '0')} ${ampm}${ap ? ' ' + ap.tzAbbr : ''}`;
}

function formatDay(absMinutes) {
  const day = Math.floor(absMinutes / 1440) + 1;
  return `Day ${Math.min(day, 7)}`;
}

function formatGameTime(absMinutes, airportId) {
  return `${formatDay(absMinutes)}, ${formatLocalTime(absMinutes, airportId)}`;
}

function formatDuration(minutes) {
  const m = Math.round(minutes);
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  const r = m % 60;
  return r === 0 ? `${h}h` : `${h}h ${r}m`;
}

// Starting clock: Monday 06:00 local at startAirport, expressed as absolute minutes.
// We anchor the week to UTC Monday 00:00, so local 06:00 = 360 - tzOffset.
function startTimeForAirport(airportId) {
  const ap = getAirportById(airportId);
  const off = ap ? ap.tzOffsetStd : -300;
  return 360 - off;
}

/* ---- schedule.js ---- */
// Timetable + fares. Timetables vary per week (seeded); fares vary per flight + deals.



function haversineMiles(lat1, lon1, lat2, lon2) {
  const R = 3959;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function getRealisticDuration(fromId, toId) {
  const from = getAirportById(fromId);
  const to = getAirportById(toId);
  if (!from || !to) return 120;
  const miles = haversineMiles(from.lat, from.lon, to.lat, to.lon);
  const raw = (miles / 475) * 60 + 30;
  return Math.max(60, Math.min(420, Math.round(raw / 15) * 15));
}

function getMilesForFlight(fromId, toId) {
  const from = getAirportById(fromId);
  const to = getAirportById(toId);
  if (!from || !to) return 500;
  return Math.round(haversineMiles(from.lat, from.lon, to.lat, to.lon) / 100) * 100;
}

// ---- Fares: base bands + seeded variability + deals ----
// Bands (agreed ranges): <500mi $129 / <1200 $229 / <2800 $349 / long-haul $499.
function baseFareForMiles(miles) {
  if (miles < 500) return 129;
  if (miles < 1200) return 229;
  if (miles < 2800) return 349;
  return 499;
}

const AIRLINE_FARE_FACTOR = { VL: 1.1, BF: 0.95, PR: 1.0, AD: 0.95, HR: 1.0 };

function dayOfWeekFactor(dayNum) {
  const dow = dayNum % 7; // 0=Mon
  if (dow === 4 || dow === 6) return 1.15; // Fri / Sun peak
  if (dow === 1 || dow === 2) return 0.9; // Tue / Wed cheap
  return 1.0;
}

function todFactor(tod) {
  if (tod >= 360 && tod < 540) return 1.05; // morning peak
  if (tod >= 1020 && tod < 1290) return 1.1; // evening peak
  if (tod < 360) return 0.85; // redeye special
  return 1.0;
}

function charmPrice(dollars) {
  // Round to $X9 endings for realism ($129, $189...), min $49.
  const rounded = Math.max(49, Math.round(dollars / 10) * 10 - 1);
  return rounded;
}

function fareForFlight({ from, to, airline, tod, weekNum, dayNum, templateId }) {
  const a = getAirportById(from);
  const b = getAirportById(to);
  const miles = a && b ? haversineMiles(a.lat, a.lon, b.lat, b.lon) : 800;
  const base = baseFareForMiles(miles);
  const rng = seededRng(`fare-${weekSeed(weekNum)}-${templateId}-d${dayNum}`);
  const jitter = 0.8 + rng() * 0.4; // ±20%
  const airlineF = AIRLINE_FARE_FACTOR[airline] ?? 1.0;
  let price = base * jitter * airlineF * dayOfWeekFactor(dayNum) * todFactor(tod);

  // Deals: ~12% of flights get a 30–50% cut, flagged for the UI.
  let deal = false;
  let dealLabel = '';
  if (rng() < 0.12) {
    const cut = 0.3 + rng() * 0.2;
    price = price * (1 - cut);
    deal = true;
    const labels = ['Deal', 'Flash sale', 'Red-eye special', 'Off-peak deal'];
    dealLabel = tod < 360 ? 'Red-eye special' : labels[Math.floor(rng() * labels.length)];
  } else if (rng() < 0.05) {
    // Rare last-minute premium on peak flights.
    price = price * 1.25;
    dealLabel = '';
  }
  const finalPrice = charmPrice(price);
  return { price: finalPrice, basePrice: base, deal, dealLabel, miles: Math.round(miles) };
}

// ---- Timetable (per-week seeded) ----
let TT_CACHE = {}; // weekNum -> { airportId: templates[] }

function frequencyForAirport(airport) {
  if (airport.capacity >= 10) return { min: 2, max: 3 };
  if (airport.capacity >= 8) return { min: 2, max: 3 };
  if (airport.capacity >= 6) return { min: 1, max: 2 };
  if (airport.capacity >= 5) return { min: 1, max: 2 };
  return { min: 1, max: 1 };
}

// Redeyes are rare in real life: mostly long flights heading east (land in the
// morning) or leaving Hawaii/Alaska. Short hops and westbound flights don't
// get a post-midnight bucket at all.
function isRedeyeEligible(fromId, toId, duration) {
  if (duration < 330) return false;
  const from = getAirportById(fromId);
  const to = getAirportById(toId);
  if (!from || !to) return false;
  if (from.region === 'hawaii' || from.region === 'alaska') return true;
  return to.tzOffsetStd > from.tzOffsetStd; // flying east
}

const MAX_REDEYES_PER_AIRPORT = 3;

function todBuckets(isRedeyeEligible) {
  if (isRedeyeEligible) {
    return [
      { start: 360, end: 600, weight: 30 },
      { start: 660, end: 900, weight: 30 },
      { start: 960, end: 1290, weight: 32 },
      { start: 1320, end: 1530, weight: 8 },
    ];
  }
  return [
    { start: 360, end: 600, weight: 30 },
    { start: 660, end: 900, weight: 30 },
    { start: 960, end: 1290, weight: 40 },
  ];
}

function pickBucket(rng, buckets) {
  const total = buckets.reduce((s, b) => s + b.weight, 0);
  let r = rng() * total;
  for (const b of buckets) {
    if (r < b.weight) return b;
    r -= b.weight;
  }
  return buckets[0];
}

function hashSlot(s) {
  let h = 0;
  for (let j = 0; j < s.length; j++) h = (Math.imul(31, h) + s.charCodeAt(j)) | 0;
  return Math.abs(h);
}

function airlineForRoute(from, to, weekNum) {
  const hubsFrom = AIRLINES.filter((a) => a.hubs.includes(from));
  if (hubsFrom.length > 0) {
    const rng = seededRng(`airline-${weekSeed(weekNum)}-hub-${from}-${to}`);
    return hubsFrom[Math.floor(rng() * hubsFrom.length)].id;
  }
  const hubsTo = AIRLINES.filter((a) => a.hubs.includes(to));
  if (hubsTo.length > 0) {
    const rng = seededRng(`airline-${weekSeed(weekNum)}-hubTo-${from}-${to}`);
    return hubsTo[Math.floor(rng() * hubsTo.length)].id;
  }
  const rng = seededRng(`airline-${weekSeed(weekNum)}-any-${from}-${to}`);
  return AIRLINES[Math.floor(rng() * AIRLINES.length)].id;
}

function buildTimetable(weekNum) {
  if (TT_CACHE[weekNum]) return TT_CACHE[weekNum];
  const tt = {};
  for (const ap of AIRPORTS) tt[ap.id] = [];
  for (const from of Object.keys(CONNECTIONS)) {
    const fromAp = getAirportById(from);
    if (!fromAp) continue;
    for (const to of CONNECTIONS[from]) {
      const toAp = getAirportById(to);
      if (!toAp) continue;
      const freq = frequencyForAirport(fromAp);
      const rngFreq = seededRng(`freq-${weekSeed(weekNum)}-${from}-${to}`);
      const n = seededInt(rngFreq, freq.min, freq.max);
      const duration = getRealisticDuration(from, to);
      const airlineId = airlineForRoute(from, to, weekNum);
      const redeyeOk = isRedeyeEligible(from, to, duration);
      for (let i = 0; i < n; i++) {
        const rng = seededRng(`tod-${weekSeed(weekNum)}-${from}-${to}-${airlineId}-${i}`);
        const bucket = pickBucket(rng, todBuckets(redeyeOk));
        let tod;
        if (bucket.end > 1440) {
          tod = rng() < 0.5 ? seededInt(rng, 0, 90) : seededInt(rng, 1320, 1439);
        } else {
          tod = seededInt(rng, bucket.start, bucket.end);
          if (rng() < 0.85) tod = Math.round(tod / 15) * 15;
          tod = Math.max(bucket.start, Math.min(bucket.end, tod));
        }
        const hsh = hashSlot(`${weekNum}-${from}-${to}-${i}`);
        const letters = ['A', 'B', 'C'];
        tt[from].push({
          id: `${from}-${to}-${airlineId}-${i}`,
          from, to, airline: airlineId,
          flightNumber: `${airlineId} ${100 + (hsh % 900)}`,
          tod, duration,
          gate: `${letters[hsh % letters.length]}${1 + (hashSlot(`${from}-${to}-${i + 7}`) % 24)}`,
        });
      }
    }
  }
  for (const k of Object.keys(tt)) {
    // Hard cap: no airport gets more than a few post-midnight departures.
    // Overflow redeyes slide into the evening bank so route frequency is kept.
    const redeyes = tt[k].filter((t) => t.tod < 120);
    if (redeyes.length > MAX_REDEYES_PER_AIRPORT) {
      const rngCap = seededRng(`redeye-cap-${weekSeed(weekNum)}-${k}`);
      for (let i = redeyes.length - 1; i > 0; i--) {
        const j = Math.floor(rngCap() * (i + 1));
        [redeyes[i], redeyes[j]] = [redeyes[j], redeyes[i]];
      }
      for (const t of redeyes.slice(MAX_REDEYES_PER_AIRPORT)) {
        const evening = 960 + (hashSlot(`eve-${t.id}`) % 330); // 4:00–9:30 PM
        t.tod = Math.round(evening / 15) * 15;
      }
    }
    tt[k].sort((a, b) => a.tod - b.tod);
  }
  TT_CACHE[weekNum] = tt;
  return tt;
}

function delayForTemplate(template, weekNum, dayNum) {
  const fromAp = getAirportById(template.from);
  const risk = fromAp ? fromAp.delayRisk : 0.12;
  const avg = fromAp ? fromAp.avgDelay : 40;
  const rng = seededRng(`delay-${weekSeed(weekNum)}-${template.id}-d${dayNum}`);
  if (rng() >= risk) return { delayed: false, delayMinutes: 0 };
  const delay = rng() < 0.7
    ? seededInt(rng, Math.max(15, avg - 15), avg + 25)
    : seededInt(rng, 35, 120);
  return { delayed: true, delayMinutes: delay };
}

function getFlightsFrom(airportId, gameTime, weekNum, windowMinutes = 1440) {
  const tt = buildTimetable(weekNum);
  const templates = tt[airportId] || [];
  const dayNum = Math.floor(gameTime / 1440);
  const flights = [];
  function materialize(dayStartVal, dayN) {
    for (const t of templates) {
      const scheduledDeparture = dayStartVal + t.tod;
      if (scheduledDeparture < gameTime) continue;
      if (scheduledDeparture >= gameTime + windowMinutes) continue;
      const { delayed, delayMinutes } = delayForTemplate(t, weekNum, dayN);
      const fare = fareForFlight({ ...t, weekNum, dayNum: dayN, templateId: t.id });
      flights.push({
        ...t,
        scheduledDeparture,
        scheduledArrival: scheduledDeparture + t.duration,
        actualDeparture: scheduledDeparture + (delayed ? delayMinutes : 0),
        actualArrival: scheduledDeparture + t.duration + (delayed ? delayMinutes : 0),
        delayed, delayMinutes,
        ...fare,
      });
    }
  }
  materialize(dayNum * 1440, dayNum);
  if (gameTime + windowMinutes > (dayNum + 1) * 1440) materialize((dayNum + 1) * 1440, dayNum + 1);
  flights.sort((a, b) => a.scheduledDeparture - b.scheduledDeparture);
  return flights;
}

// Arrivals into an airport whose wheels-down falls in [gameTime - pastMinutes, gameTime + futureMinutes).
// Needed by the people engine: connecting pax arrive on these, terminating pax vanish on these.
function getArrivalsTo(airportId, gameTime, weekNum, pastMinutes = 720, futureMinutes = 120) {
  const tt = buildTimetable(weekNum);
  const arrivals = [];
  const lo = gameTime - pastMinutes;
  const hi = gameTime + futureMinutes;
  // Allow day -1 (Sunday) so Monday-morning connectors exist at week start.
  const dayLo = Math.floor(lo / 1440);
  const dayHi = Math.floor(hi / 1440);
  for (const from of Object.keys(tt)) {
    for (const t of tt[from]) {
      if (t.to !== airportId) continue;
      for (let dayN = dayLo; dayN <= dayHi; dayN++) {
        const scheduledDeparture = dayN * 1440 + t.tod;
        const { delayed, delayMinutes } = delayForTemplate(t, weekNum, dayN);
        const actualArrival = scheduledDeparture + t.duration + (delayed ? delayMinutes : 0);
        if (actualArrival < lo || actualArrival >= hi) continue;
        arrivals.push({
          ...t,
          scheduledDeparture,
          scheduledArrival: scheduledDeparture + t.duration,
          actualDeparture: scheduledDeparture + (delayed ? delayMinutes : 0),
          actualArrival,
          delayed, delayMinutes,
        });
      }
    }
  }
  arrivals.sort((a, b) => a.actualArrival - b.actualArrival);
  return arrivals;
}

function _resetTimetable() { TT_CACHE = {}; }

/* ---- people.js ---- */
// People engine — every NPC is bound to real flights, never random ambient spawns.
// - Connecting pax: inbound arrival A + outbound departure D, visible A.actualArrival → D.schedDep - 30.
// - Originating pax: outbound D only, visible D.schedDep - ~2h → D.schedDep - 30.
// - Terminating pax (inbound, no outbound): exit the terminal, never listed.




const BOARDING_CUTOFF = 30; // people vanish 30m before departure
const MAX_LAYOVER = 600; // 10h cap on connections we model
const MIN_CONNECT = 45;

const _cache = new Map(); // `${week}:${airport}:${timeBucket}` -> people[]

function timeBucket(gameTime) {
  return Math.floor(gameTime / 15); // 15m buckets keep lists stable while browsing
}

function makeIdentity(rng) {
  return {
    name: seededPick(rng, FIRST_NAMES),
    age: seededInt(rng, 21, 55),
    avatar: seededPick(rng, AVATARS),
    background: seededPick(rng, BACKGROUNDS),
  };
}

function makeInterests(rng) {
  const pool = [...INTERESTS_ALL];
  // seeded shuffle
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const nVis = seededInt(rng, 2, 5);
  const nHid = seededInt(rng, 1, 3);
  return { interests: pool.slice(0, nVis), hiddenInterests: pool.slice(nVis, nVis + nHid) };
}

function scoreTier(person, playerInterests) {
  if (!playerInterests || playerInterests.length === 0) return { shared: 0, score: 0, tier: 'Cold' };
  const all = new Set([...person.interests, ...person.hiddenInterests]);
  let shared = 0;
  for (const p of playerInterests) if (all.has(p)) shared++;
  const score = Math.min(1, shared / 3);
  const tier = shared >= 3 ? 'Hot' : shared >= 1 ? 'Warm' : 'Cold';
  return { shared, score, tier };
}

function buildPerson({ seedStr, inbound, outbound, availableFrom, availableUntil, gameTime, playerInterests }) {
  const rng = seededRng(seedStr);
  const id = makeIdentity(rng);
  const ints = makeInterests(rng);
  const person = {
    id: seedStr,
    ...id,
    ...ints,
    inboundFlight: inbound
      ? { id: inbound.id, from: inbound.from, flightNumber: inbound.flightNumber, actualArrival: inbound.actualArrival }
      : null,
    outboundFlight: {
      id: outbound.id, to: outbound.to, flightNumber: outbound.flightNumber,
      scheduledDeparture: outbound.scheduledDeparture,
    },
    availableFrom,
    availableUntil,
    minutesLeft: Math.max(0, Math.round(availableUntil - gameTime)),
  };
  const s = scoreTier(person, playerInterests);
  person.shared = s.shared;
  person.matchScore = s.score;
  person.tier = s.tier;
  return person;
}

function getPeopleAt(airportId, gameTime, weekNum, playerInterests = []) {
  const key = `${weekNum}:${airportId}:${timeBucket(gameTime)}:${[...playerInterests].sort().join(',')}`;
  if (_cache.has(key)) return _cache.get(key);

  const ap = getAirportById(airportId);
  const isHub = !!(ap && ap.isHub);
  // Only departures in the next 6h can have people waiting; connections need
  // arrivals from the past 10h. Shorter window keeps hubs at 4–9 people.
  const departures = getFlightsFrom(airportId, gameTime, weekNum, 360);
  const arrivals = getArrivalsTo(airportId, gameTime, weekNum, MAX_LAYOVER, 30);
  const landed = arrivals.filter((a) => a.actualArrival <= gameTime);
  const people = [];

  for (const d of departures) {
    const rngD = seededRng(`dep-pax-${weekSeed(weekNum)}-${d.id}`);
    const until = d.scheduledDeparture - BOARDING_CUTOFF;

    // 1) Originating pax: show up 1–2h before their flight.
    const nOrig = isHub ? (rngD() < 0.4 ? (rngD() < 0.25 ? 2 : 1) : 0) : (rngD() < 0.35 ? 1 : 0);
    for (let i = 0; i < nOrig; i++) {
      const rng = seededRng(`orig-w-${weekSeed(weekNum)}-${d.id}-${i}`);
      const showUp = 60 + Math.floor(rng() * 60); // 60–120m before
      const from = d.scheduledDeparture - showUp;
      if (gameTime < from || gameTime >= until) continue;
      people.push(buildPerson({
        seedStr: `pax-${weekNum}-${airportId}-${d.id}-orig-${i}`,
        inbound: null, outbound: d, availableFrom: from, availableUntil: until,
        gameTime, playerInterests,
      }));
    }

    // 2) Connecting pax: sample up to 2 valid inbound arrivals per departure.
    const valid = landed.filter((a) => {
      const layover = d.scheduledDeparture - BOARDING_CUTOFF - a.actualArrival;
      return layover >= MIN_CONNECT && layover <= MAX_LAYOVER;
    });
    // seeded shuffle so the same connections win every load
    for (let i = valid.length - 1; i > 0; i--) {
      const j = Math.floor(rngD() * (i + 1));
      [valid[i], valid[j]] = [valid[j], valid[i]];
    }
    const maxConn = isHub ? 2 : 1;
    const roll = rngD();
    const nConn = roll < 0.55 ? 0 : roll < 0.85 ? 1 : maxConn;
    for (let i = 0; i < Math.min(nConn, valid.length); i++) {
      const a = valid[i];
      const from = a.actualArrival;
      if (gameTime < from || gameTime >= until) continue;
      people.push(buildPerson({
        seedStr: `pax-${weekNum}-${airportId}-${a.id}-${d.id}`,
        inbound: a, outbound: d, availableFrom: from, availableUntil: until,
        gameTime, playerInterests,
      }));
    }
    if (people.length >= 9) break;
  }

  // Sort: best match first, then least time left (urgency).
  const tierRank = { Hot: 0, Warm: 1, Cold: 2 };
  people.sort((x, y) => (tierRank[x.tier] - tierRank[y.tier]) || (x.minutesLeft - y.minutesLeft));
  _cache.set(key, people);
  if (_cache.size > 400) _cache.clear();
  return people;
}

// Global intel: counts + high-level vibe ONLY (no times, no interests, no names).
function getIntel(airportId, gameTime, weekNum, playerInterests = []) {
  const people = getPeopleAt(airportId, gameTime, weekNum, playerInterests);
  let vibe = 'Quiet';
  if (people.some((p) => p.tier === 'Hot')) vibe = 'Hot';
  else if (people.some((p) => p.tier === 'Warm')) vibe = 'Warm';
  else if (people.length > 0) vibe = 'Cold';
  return { airportId, count: people.length, vibe };
}

function getIntelForAll(gameTime, weekNum, playerInterests = []) {
  return AIRPORTS.map((a) => getIntel(a.id, gameTime, weekNum, playerInterests))
    .sort((x, y) => {
      const rank = { Hot: 0, Warm: 1, Cold: 2, Quiet: 3 };
      if (rank[x.vibe] !== rank[y.vibe]) return rank[x.vibe] - rank[y.vibe];
      return y.count - x.count;
    });
}

function _clearPeopleCache() { _cache.clear(); }

/* ---- encounters.js ---- */
// Encounter engine — time is the cost, points are activity base × match multiplier.
// Success rolls use live randomness (the universe is seeded, the spark is not).


const MEET_BASE_MINUTES = 15; // saying hi always costs a quarter hour
const CONSOLATION_POINTS = 5; // all-fail encounters still earn a little
const MAX_ACTIVITIES = 3;

// Multiplier agreed: 0.5x (no overlap) → 2.0x (full overlap).
function matchMultiplier(matchScore) {
  const s = Math.max(0, Math.min(1, matchScore));
  return 0.5 + s * 1.5;
}

// Rush penalty when their flight is close: mirrors layover pressure.
function rushPenalty(minutesLeft) {
  if (minutesLeft < 60) return 0.2;
  if (minutesLeft < 120) return 0.1;
  return 0;
}

function eligibleActivities(person) {
  return ACTIVITIES.filter((a) => (a.requireMatch ?? 0) <= person.matchScore);
}

function successChance(activity, person, loungeBonus = 0) {
  const sharedTag =
    person.interests.includes(activity.interestTag) ||
    person.hiddenInterests.includes(activity.interestTag);
  const p = 0.35 + person.matchScore * 0.45 + (sharedTag ? 0.1 : 0) - rushPenalty(person.minutesLeft) + loungeBonus;
  return Math.max(0.15, Math.min(0.95, p));
}

// Fit check: meet base + chosen activities must fit inside minutesLeft.
function fitActivities(activityNames, minutesLeft) {
  const chosen = activityNames
    .map((n) => ACTIVITIES.find((a) => a.name === n))
    .filter(Boolean);
  let total = MEET_BASE_MINUTES;
  const fitted = [];
  for (const act of chosen) {
    if (total + act.duration <= minutesLeft) {
      fitted.push(act);
      total += act.duration;
    }
  }
  return { fitted, totalTime: fitted.length === 0 ? Math.min(MEET_BASE_MINUTES, minutesLeft) : total, trimmed: fitted.length < chosen.length };
}

function runEncounter(person, activityNames, rand = Math.random, loungeBonus = 0) {
  const mult = matchMultiplier(person.matchScore);
  const { fitted, totalTime, trimmed } = fitActivities(activityNames, person.minutesLeft);
  const results = fitted.map((act) => {
    const success = rand() < successChance(act, person, loungeBonus);
    const points = success ? Math.round(act.basePoints * mult) : 0;
    return { name: act.name, duration: act.duration, basePoints: act.basePoints, success, points };
  });
  let totalPoints = results.reduce((s, r) => s + r.points, 0);
  const allFail = fitted.length > 0 && totalPoints === 0;
  if (allFail) totalPoints = CONSOLATION_POINTS;
  return {
    personId: person.id,
    personName: person.name,
    matchScore: person.matchScore,
    tier: person.tier,
    multiplier: Math.round(mult * 100) / 100,
    results,
    totalPoints,
    totalTime,
    trimmed,
    consolation: allFail,
    loungeBoost: loungeBonus > 0,
  };
}

/* ---- loyalty.js ---- */
// Loyalty + wallet + lounge. State lives in the per-week trip object (see app.js).



const TIERS = ['member', 'silver', 'gold', 'platinum'];
const TIER_THRESHOLDS = {
  silver: { miles: 4000, segments: 6 },
  gold: { miles: 12000, segments: 15 },
  platinum: { miles: 25000, segments: 30 },
};
const TIER_BONUS_POINTS = { member: 1, silver: 1.25, gold: 1.5, platinum: 2 }; // pts per mile
const LOUNGE_PASS_COST = 25; // dollars
const LOUNGE_PASS_MINUTES = 240;

function blankLoyalty() {
  const o = {};
  for (const al of AIRLINES) o[al.id] = { miles: 0, segments: 0, points: 0, tier: 'member', lastActiveWeek: null };
  return o;
}

// Fill gaps from older/partial saves so every airline always has a record.
function ensureRecs(store) {
  if (!store.recs) store.recs = {};
  const fresh = blankLoyalty();
  for (const al of AIRLINES) {
    if (!store.recs[al.id]) store.recs[al.id] = fresh[al.id];
    else {
      const r = store.recs[al.id];
      if (r.miles == null) r.miles = 0;
      if (r.segments == null) r.segments = 0;
      if (r.points == null) r.points = 0;
      if (!r.tier) r.tier = 'member';
    }
  }
  return store;
}

function tierFor(miles, segments) {
  if (miles >= TIER_THRESHOLDS.platinum.miles || segments >= TIER_THRESHOLDS.platinum.segments) return 'platinum';
  if (miles >= TIER_THRESHOLDS.gold.miles || segments >= TIER_THRESHOLDS.gold.segments) return 'gold';
  if (miles >= TIER_THRESHOLDS.silver.miles || segments >= TIER_THRESHOLDS.silver.segments) return 'silver';
  return 'member';
}

// Status erosion: skip a full week on an airline → miles halve, segments reset.
function applyErosion(loyalty, weekNum) {
  const eroded = [];
  for (const al of AIRLINES) {
    const rec = loyalty[al.id];
    if (!rec || rec.lastActiveWeek == null) continue;
    if (rec.lastActiveWeek <= weekNum - 2 && (rec.miles > 0 || rec.segments > 0)) {
      rec.miles = Math.floor(rec.miles / 2);
      rec.segments = 0;
      rec.tier = tierFor(rec.miles, rec.segments);
      eroded.push(al.id);
    }
  }
  return eroded;
}

function nextTierProgress(rec) {
  if (rec.tier === 'platinum') return { next: null, pct: 100, needMiles: 0, needSeg: 0 };
  const order = { member: 'silver', silver: 'gold', gold: 'platinum' };
  const next = order[rec.tier];
  const th = TIER_THRESHOLDS[next];
  return {
    next,
    pct: Math.round(Math.max(Math.min(1, rec.miles / th.miles), Math.min(1, rec.segments / th.segments)) * 100),
    needMiles: Math.max(0, th.miles - rec.miles),
    needSeg: Math.max(0, th.segments - rec.segments),
  };
}

// Points price for a free flight, by distance band.
function pointsPriceForMiles(miles) {
  if (miles < 500) return 4000;
  if (miles < 1200) return 8000;
  return 12000;
}

function earnForFlight(loyalty, airlineId, fromId, toId, weekNum) {
  const miles = getMilesForFlight(fromId, toId);
  const rec = loyalty[airlineId];
  const mult = TIER_BONUS_POINTS[rec.tier] ?? 1;
  const pts = Math.round(miles * mult);
  rec.miles += miles;
  rec.segments += 1;
  rec.points += pts;
  rec.lastActiveWeek = weekNum;
  rec.tier = tierFor(rec.miles, rec.segments);
  return { miles, points: pts, tier: rec.tier };
}

// ---- wallet ----
function budgetFor(difficulty) {
  return DIFFICULTIES[difficulty]?.budget ?? null; // null = unlimited
}

function canAffordCash(trip, price) {
  const budget = budgetFor(trip.difficulty);
  if (budget == null) return true;
  return trip.spent + price <= budget;
}

// ---- lounge ----
function loungeAccess(trip, airlineId, airportId) {
  const airline = getAirlineById(airlineId);
  if (!airline || !airline.hubs.includes(airportId)) return { ok: false, via: null };
  const rec = trip.loyalty[airlineId];
  if (rec && (rec.tier === 'gold' || rec.tier === 'platinum')) return { ok: true, via: 'status' };
  if (trip.loungePass && trip.loungePass.airline === airlineId && trip.loungePass.expires > trip.gameTime) {
    return { ok: true, via: 'pass' };
  }
  return { ok: false, via: null };
}

function anyLoungeAccess(trip, airportId) {
  return AIRLINES.filter((a) => a.hubs.includes(airportId))
    .map((a) => ({ airline: a, ...loungeAccess(trip, a.id, airportId) }))
    .find((x) => x.ok) || null;
}

function loungeBonus(trip, airportId) {
  return anyLoungeAccess(trip, airportId) ? 0.15 : 0;
}

function buyLoungePass(trip, airlineId) {
  const access = loungeAccess(trip, airlineId, trip.airport);
  if (access.ok) return { ok: false, reason: 'Already have access' };
  if (!canAffordCash(trip, LOUNGE_PASS_COST)) return { ok: false, reason: 'Over budget' };
  trip.spent += LOUNGE_PASS_COST;
  trip.loungePass = { airline: airlineId, expires: trip.gameTime + LOUNGE_PASS_MINUTES };
  return { ok: true };
}

/* ---- app.js ---- */
// Phase 4: flights you buy, budgets, loyalty + points, lounge, erosion.







const weekInput = document.getElementById('week-input');
const airportInput = document.getElementById('airport-input');
const difficultyInput = document.getElementById('difficulty-input');
const listEl = document.getElementById('flight-list');
const peopleEl = document.getElementById('people-list');
const intelEl = document.getElementById('intel-list');
const loyaltyEl = document.getElementById('loyalty-list');
const clockEl = document.getElementById('clock-line');
const walletEl = document.getElementById('wallet-line');
const scoreEl = document.getElementById('score-line');
const arrivalEl = document.getElementById('arrival-line');
const pickerEl = document.getElementById('interest-picker');
const loungeBannerEl = document.getElementById('lounge-banner');
const modalEl = document.getElementById('encounter-modal');
const charBarEl = document.getElementById('char-bar');
const charModalEl = document.getElementById('char-modal');
const profileCharEl = document.getElementById('profile-char');
const currentWeekEl = document.getElementById('current-week-line');

let trip = null;
let currentWeek = 1; // setup inputs never drive the game directly; only actions do
let activeTab = 'flights';
let encounterTarget = null;
let encounterPicked = new Set();
let arrivalMsg = '';
let erosionMsg = '';
let charMenuOpen = false;
let draftAvatar = AVATARS[0];
let draftInterests = new Set();

function getWeek() { return currentWeek; }

// ---- characters: interests are permanent, chosen once at creation ----
function loadChars() {
  try {
    const raw = localStorage.getItem('ca_chars');
    const list = raw ? JSON.parse(raw) : [];
    return Array.isArray(list) ? list.filter((c) => c && c.id && Array.isArray(c.interests)) : [];
  } catch { return []; }
}

function saveChars(list) {
  try { localStorage.setItem('ca_chars', JSON.stringify(list)); } catch { /* ignore */ }
}

function activeChar() {
  const list = loadChars();
  if (list.length === 0) return null;
  try {
    const id = localStorage.getItem('ca_active');
    const found = list.find((c) => c.id === id);
    if (found) return found;
  } catch { /* ignore */ }
  return list[0];
}

function setActiveChar(id) {
  try { localStorage.setItem('ca_active', id); } catch { /* ignore */ }
  trip = null;
  arrivalMsg = '';
  erosionMsg = '';
  charMenuOpen = false;
}

// One-time migration: pre-character saves move under the first character.
function migrateLegacyTo(cid) {
  try {
    const loy = localStorage.getItem('ca_loyalty');
    if (loy != null) {
      localStorage.setItem(`ca_loyalty_${cid}`, loy);
      localStorage.removeItem('ca_loyalty');
    }
    for (let w = 1; w <= 53; w++) {
      for (const k of ['trip', 'score', 'met', 'log']) {
        const oldK = `ca_${k}_w${w}`;
        const v = localStorage.getItem(oldK);
        if (v != null) {
          localStorage.setItem(`ca_${k}_${cid}_w${w}`, v);
          localStorage.removeItem(oldK);
        }
      }
    }
    localStorage.removeItem('ca_interests');
  } catch { /* ignore */ }
}

function legacyInterests() {
  try {
    const raw = localStorage.getItem('ca_interests');
    if (raw) return JSON.parse(raw).slice(0, MAX_INTERESTS);
  } catch { /* ignore */ }
  return null;
}

function hasLegacySaves() {
  try {
    if (localStorage.getItem('ca_interests') || localStorage.getItem('ca_loyalty')) return true;
    for (let w = 1; w <= 53; w++) {
      if (localStorage.getItem(`ca_trip_w${w}`)) return true;
    }
  } catch { /* ignore */ }
  return false;
}

// Returns chars (maybe empty — caller opens the creation modal then).
function ensureChars() {
  const list = loadChars();
  if (list.length > 0) return list;
  if (hasLegacySaves()) {
    const cid = 'c_' + Date.now().toString(36);
    const interests = legacyInterests() || ['coffee', 'hookup', 'sex'];
    saveChars([{ id: cid, name: 'Traveler', avatar: AVATARS[2], interests, createdAt: Date.now() }]);
    setActiveChar(cid);
    migrateLegacyTo(cid);
    return loadChars();
  }
  return [];
}

// ---- persistence (per character per week) ----
function cid() { const c = activeChar(); return c ? c.id : 'none'; }
function tripKey() { return `ca_trip_${cid()}_w${getWeek()}`; }
function scoreKey() { return `ca_score_${cid()}_w${getWeek()}`; }
function metKey() { return `ca_met_${cid()}_w${getWeek()}`; }
function logKey() { return `ca_log_${cid()}_w${getWeek()}`; }

function loadTrip() {
  try {
    const raw = localStorage.getItem(tripKey());
    if (raw) {
      const t = JSON.parse(raw);
      if (t && t.airport && getAirportById(t.airport)) return t;
    }
  } catch { /* ignore */ }
  return null;
}

function initTrip() {
  const airport = airportInput.value;
  trip = {
    airport,
    gameTime: startTimeForAirport(airport),
    difficulty: difficultyInput.value || 'medium',
    spent: 0,
    loungePass: null,
    locked: false, // interests stay editable until the first action
  };
  saveTrip();
}

function getInterests() {
  const c = activeChar();
  return c ? [...c.interests] : [];
}

// The week-started flag is kept on the trip for save compat; interests
// themselves are permanent on the character and never edited after creation.
function lockWeek() {
  if (trip && !trip.locked) {
    trip.locked = true;
    saveTrip();
  }
}

function saveTrip() {
  try { localStorage.setItem(tripKey(), JSON.stringify(trip)); } catch { /* ignore */ }
}

function loadLoyalty() {
  try {
    const raw = localStorage.getItem(`ca_loyalty_${cid()}`);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && parsed.recs) return ensureRecs(parsed);
    }
  } catch { /* ignore */ }
  return { recs: blankLoyalty(), erosionWeek: null };
}

function saveLoyalty(store) {
  try { localStorage.setItem(`ca_loyalty_${cid()}`, JSON.stringify(store)); } catch { /* ignore */ }
}

function loyaltyStore() {
  const store = loadLoyalty();
  const week = getWeek();
  if (store.erosionWeek !== week) {
    const eroded = applyErosion(store.recs, week);
    store.erosionWeek = week;
    saveLoyalty(store);
    erosionMsg = eroded.length > 0
      ? `Status eroded on ${eroded.join(', ')} — skipped a full week, miles halved.`
      : '';
  }
  return store;
}

function getScore() {
  try { return parseInt(localStorage.getItem(scoreKey()) || '0', 10) || 0; }
  catch { return 0; }
}
function addScore(n) {
  const v = getScore() + n;
  try { localStorage.setItem(scoreKey(), String(v)); } catch { /* ignore */ }
  return v;
}
function getMetIds() {
  try { return new Set(JSON.parse(localStorage.getItem(metKey()) || '[]')); }
  catch { return new Set(); }
}
function markMet(id) {
  const s = getMetIds();
  s.add(id);
  try { localStorage.setItem(metKey(), JSON.stringify([...s].slice(-500))); } catch { /* ignore */ }
}
function logEncounter(entry) {
  try {
    const raw = JSON.parse(localStorage.getItem(logKey()) || '[]');
    raw.unshift({ ...entry, at: Date.now() });
    localStorage.setItem(logKey(), JSON.stringify(raw.slice(0, 100)));
  } catch { /* ignore */ }
}

function getInterests() {
  try {
    const raw = localStorage.getItem('ca_interests');
    if (raw) return JSON.parse(raw).slice(0, MAX_INTERESTS);
  } catch { /* ignore */ }
  return ['coffee', 'hookup', 'sex'];
}

function renderPicker() {
  const c = activeChar();
  const mine = new Set(c ? c.interests : []);
  pickerEl.innerHTML = '';
  const note = document.createElement('div');
  note.className = 'lock-note';
  note.textContent = c
    ? `${c.avatar} ${c.name}'s interests — permanent, chosen at creation.`
    : 'Create a character to begin.';
  pickerEl.appendChild(note);
  for (const tag of INTERESTS_ALL) {
    const chip = document.createElement('button');
    chip.className = 'chip' + (mine.has(tag) ? ' selected' : '');
    chip.textContent = tag;
    chip.disabled = true;
    chip.title = c ? 'Permanent — set at character creation' : '';
    pickerEl.appendChild(chip);
  }
}

function renderCharBar() {
  const c = activeChar();
  charBarEl.innerHTML = '';
  if (!c) {
    const b = document.createElement('button');
    b.className = 'btn btn-primary btn-small';
    b.textContent = '＋ New traveler';
    b.addEventListener('click', () => openCharModal(true));
    charBarEl.appendChild(b);
    return;
  }
  const btn = document.createElement('button');
  btn.className = 'char-btn';
  btn.innerHTML = `<span class="char-avatar">${c.avatar}</span> <span>${c.name}</span> <span class="char-caret">▾</span>`;
  btn.addEventListener('click', () => { charMenuOpen = !charMenuOpen; renderCharBar(); });
  charBarEl.appendChild(btn);
  if (!charMenuOpen) return;
  const menu = document.createElement('div');
  menu.className = 'char-menu';
  for (const other of loadChars()) {
    const item = document.createElement('button');
    item.className = 'char-item' + (other.id === c.id ? ' active' : '');
    item.innerHTML = `<span>${other.avatar}</span> <span>${other.name}</span> <span class="flight-sub">${other.interests.length} interests</span>`;
    if (other.id !== c.id) {
      const id = other.id;
      item.addEventListener('click', () => { setActiveChar(id); render(); });
    }
    menu.appendChild(item);
  }
  const add = document.createElement('button');
  add.className = 'char-item new';
  add.textContent = '＋ New traveler';
  add.addEventListener('click', () => { charMenuOpen = false; openCharModal(false); });
  menu.appendChild(add);
  charBarEl.appendChild(menu);
}

function openCharModal(mustCreate) {
  draftAvatar = AVATARS[0];
  draftInterests = new Set();
  renderCharDraft(mustCreate, '');
  charModalEl.style.display = 'flex';
}

function closeCharModal() {
  charModalEl.style.display = 'none';
}

function renderCharDraft(mustCreate, error) {
  charModalEl.innerHTML = `
    <div class="modal-card">
      <h3>${mustCreate && loadChars().length === 0 ? 'Create your traveler' : 'New traveler'}</h3>
      <div class="flight-sub">Name, face, and 2–5 interests — permanent for this character's whole career.</div>
      <input id="char-name" class="name-input" maxlength="20" placeholder="Name..." value="">
      <div class="section-title">Face</div>
      <div class="avatar-grid">
        ${AVATARS.map((a) => `<button class="avatar-option${a === draftAvatar ? ' selected' : ''}" data-avatar="${a}">${a}</button>`).join('')}
      </div>
      <div class="section-title">Interests — pick ${MAX_INTERESTS} max (${draftInterests.size} picked)</div>
      <div class="chip-grid">
        ${INTERESTS_ALL.map((t) => `<button class="chip${draftInterests.has(t) ? ' selected' : ''}" data-interest="${t}">${t}</button>`).join('')}
      </div>
      ${error ? `<div class="form-error">${error}</div>` : ''}
      <div class="modal-actions">
        ${mustCreate && loadChars().length === 0 ? '' : '<button class="btn btn-small" id="char-cancel">Cancel</button>'}
        <button class="btn btn-primary btn-small" id="char-create">Create</button>
      </div>
    </div>`;
  charModalEl.querySelectorAll('[data-avatar]').forEach((b) => {
    b.addEventListener('click', () => {
      draftAvatar = b.dataset.avatar;
      charModalEl.querySelectorAll('[data-avatar]').forEach((x) => x.classList.toggle('selected', x.dataset.avatar === draftAvatar));
    });
  });
  charModalEl.querySelectorAll('[data-interest]').forEach((b) => {
    b.addEventListener('click', () => {
      const t = b.dataset.interest;
      if (draftInterests.has(t)) draftInterests.delete(t);
      else {
        if (draftInterests.size >= MAX_INTERESTS) return;
        draftInterests.add(t);
      }
      b.classList.toggle('selected', draftInterests.has(t));
      renderCharDraftCount();
    });
  });
  const cancel = charModalEl.querySelector('#char-cancel');
  if (cancel) cancel.addEventListener('click', closeCharModal);
  charModalEl.querySelector('#char-create').addEventListener('click', () => {
    const name = (charModalEl.querySelector('#char-name').value || '').trim().slice(0, 20);
    if (!name) { renderCharDraft(mustCreate, 'Give your traveler a name.'); return; }
    if (draftInterests.size < 2) { renderCharDraft(mustCreate, 'Pick at least 2 interests — they last forever.'); return; }
    const list = loadChars();
    const id = 'c_' + Date.now().toString(36);
    list.push({ id, name, avatar: draftAvatar, interests: [...draftInterests], createdAt: Date.now() });
    saveChars(list);
    setActiveChar(id);
    closeCharModal();
    render();
  });
  if (!mustCreate || loadChars().length > 0) {
    charModalEl.onclick = (e) => { if (e.target === charModalEl) closeCharModal(); };
  } else {
    charModalEl.onclick = null;
  }
}

function renderCharDraftCount() {
  const titles = charModalEl.querySelectorAll('.section-title');
  const last = titles[titles.length - 1];
  if (last) last.textContent = `Interests — pick ${MAX_INTERESTS} max (${draftInterests.size} picked)`;
}

function visiblePeople(weekNum) {
  const met = getMetIds();
  return getPeopleAt(trip.airport, trip.gameTime, weekNum, getInterests()).filter((p) => !met.has(p.id));
}

// ---- booking ----
function bookFlight(f, usePoints) {
  const week = getWeek();
  const store = loyaltyStore();
  const from = trip.airport;
  if (usePoints) {
    const cost = pointsPriceForMiles(f.miles);
    const rec = store.recs[f.airline];
    if (!rec || rec.points < cost) return;
    rec.points -= cost;
  } else {
    if (!canAffordCash(trip, f.price)) return;
    trip.spent += f.price;
  }
  trip.airport = f.to;
  trip.gameTime = f.actualArrival; // no booking ahead: you board now, time jumps to arrival
  lockWeek();
  const earned = earnForFlight(store.recs, f.airline, from, f.to, week);
  saveLoyalty(store);
  const al = getAirlineById(f.airline);
  arrivalMsg = `Arrived ${f.to}${f.delayed ? ` (delayed +${formatDuration(f.delayMinutes)})` : ''} · +${earned.miles.toLocaleString()} mi +${earned.points.toLocaleString()} pts ${al ? al.name : ''} (${earned.tier})`;
  saveTrip();
  render();
}

function renderFlights(weekNum, store) {
  const flights = getFlightsFrom(trip.airport, trip.gameTime, weekNum, 1440).slice(0, 20);
  listEl.innerHTML = '';
  if (flights.length === 0) {
    listEl.innerHTML = '<div class="flight-row"><div class="flight-sub">No departures — advance time.</div></div>';
    return;
  }
  for (const f of flights) {
    const al = getAirlineById(f.airline);
    const affordCash = canAffordCash(trip, f.price);
    const ptsCost = pointsPriceForMiles(f.miles);
    const affordPts = (store.recs[f.airline]?.points ?? 0) >= ptsCost;
    const row = document.createElement('div');
    row.className = 'flight-row' + (f.deal ? ' deal' : '');
    row.innerHTML = `
      <div class="flight-main">
        <div class="flight-route">${f.from} → ${f.to} · ${al ? al.name : f.airline} ${f.flightNumber}</div>
        <div class="flight-sub">Dep ${formatLocalTime(f.scheduledDeparture, f.from)} · Arr ${formatLocalTime(f.actualArrival, f.to)} · ${formatDuration(f.duration)} · Gate ${f.gate}</div>
        <div class="flight-sub">${f.delayed ? `<span class="delayed-tag">Delayed +${formatDuration(f.delayMinutes)}</span> · ` : ''}${f.miles.toLocaleString()} mi · ${ptsCost.toLocaleString()} pts award</div>
        ${f.deal ? `<span class="deal-tag">✨ ${f.dealLabel}</span>` : ''}
      </div>
      <div class="flight-actions">
        <div class="flight-price">$${f.price}</div>
        <button class="btn-book" ${affordCash ? '' : 'disabled'}>Book</button>
        <button class="btn-book pts" ${affordPts ? '' : 'disabled'}>${ptsCost.toLocaleString()} pts</button>
      </div>`;
    const [cashBtn, ptsBtn] = row.querySelectorAll('.btn-book');
    cashBtn.title = affordCash ? `Fly now for $${f.price}` : 'Over budget';
    ptsBtn.title = affordPts ? `Redeem ${ptsCost.toLocaleString()} ${al ? al.name : ''} points` : `Need ${ptsCost.toLocaleString()} pts`;
    cashBtn.addEventListener('click', () => bookFlight(f, false));
    ptsBtn.addEventListener('click', () => bookFlight(f, true));
    listEl.appendChild(row);
  }
}

function renderLoungeBanner(store) {
  const lounges = AIRLINES.filter((a) => a.hubs.includes(trip.airport));
  if (lounges.length === 0) {
    loungeBannerEl.style.display = 'none';
    return;
  }
  loungeBannerEl.style.display = '';
  const access = anyLoungeAccess({ ...trip, loyalty: store.recs }, trip.airport);
  if (access) {
    loungeBannerEl.className = 'lounge-banner has-access';
    loungeBannerEl.innerHTML = `
      <div><strong>${access.airline.icon} ${access.airline.lounge}</strong> — access granted (${access.via === 'status' ? store.recs[access.airline.id].tier : 'day pass'})</div>
      <div class="flight-sub">Encounters here get +15% success.</div>`;
    return;
  }
  loungeBannerEl.className = 'lounge-banner';
  loungeBannerEl.innerHTML = `
    <div><strong>No lounge access here.</strong> <span class="flight-sub">Day pass $25 · 4h · +15% encounter success</span></div>
    <div class="pass-row"></div>`;
  const row = loungeBannerEl.querySelector('.pass-row');
  for (const a of lounges) {
    const b = document.createElement('button');
    b.className = 'btn btn-small';
    b.textContent = `${a.icon} ${a.id} pass $25`;
    b.disabled = !canAffordCash(trip, LOUNGE_PASS_COST);
    b.addEventListener('click', () => {
      const res = buyLoungePass({ ...trip, loyalty: store.recs }, a.id);
      if (!res.ok) { arrivalMsg = res.reason; render(); return; }
      trip.spent += LOUNGE_PASS_COST;
      trip.loungePass = { airline: a.id, expires: trip.gameTime + LOUNGE_PASS_MINUTES };
      arrivalMsg = `${a.lounge} day pass — 4h of +15% encounters.`;
      saveTrip();
      render();
    });
    row.appendChild(b);
  }
}

function renderPeople(weekNum, store) {
  renderLoungeBanner(store);
  const people = visiblePeople(weekNum);
  peopleEl.innerHTML = '';
  if (people.length === 0) {
    peopleEl.innerHTML = '<div class="person-card"><div class="flight-sub">Nobody here right now. Advance time — crowds build around arrivals and 1–2h before departures.</div></div>';
    return;
  }
  for (const p of people) {
    const card = document.createElement('div');
    card.className = 'person-card';
    const route = p.inboundFlight
      ? `in ${p.inboundFlight.from} → out ${p.outboundFlight.to} ${p.outboundFlight.flightNumber}`
      : `originating → out ${p.outboundFlight.to} ${p.outboundFlight.flightNumber}`;
    card.innerHTML = `
      <div class="person-top">
        <span class="person-avatar">${p.avatar}</span>
        <div><div class="person-name">${p.name}, ${p.age}</div>
        <div class="flight-sub">${p.background} · ${route}</div></div>
        <span class="tier tier-${p.tier.toLowerCase()}">${p.tier}</span>
      </div>
      <div class="person-bottom">
        <span class="flight-sub">⏱ ${formatDuration(p.minutesLeft)} left · ${p.shared} shared interest${p.shared === 1 ? '' : 's'}</span>
        <button class="btn btn-meet">Meet</button>
      </div>`;
    card.querySelector('.btn-meet').addEventListener('click', () => openEncounter(p, store));
    peopleEl.appendChild(card);
  }
}

function renderIntel(weekNum) {
  const rows = getIntelForAll(trip.gameTime, weekNum, getInterests());
  intelEl.innerHTML = '';
  for (const r of rows.slice(0, 24)) {
    const ap = getAirportById(r.airportId);
    const div = document.createElement('div');
    div.className = 'intel-row' + (r.airportId === trip.airport ? ' current' : '');
    div.innerHTML = `
      <span class="intel-code">${r.airportId}</span>
      <span class="intel-name">${ap ? ap.name : ''}</span>
      <span class="intel-count">${r.count} here</span>
      <span class="tier tier-${r.vibe.toLowerCase()}">${r.vibe}</span>`;
    intelEl.appendChild(div);
  }
}

function renderLoyalty(weekNum, store) {
  loyaltyEl.innerHTML = '';
  if (erosionMsg) {
    const d = document.createElement('div');
    d.className = 'erosion-note';
    d.textContent = erosionMsg;
    loyaltyEl.appendChild(d);
  }
  for (const al of AIRLINES) {
    const rec = store.recs[al.id];
    const prog = nextTierProgress(rec);
    const card = document.createElement('div');
    card.className = 'loyalty-card';
    card.style.borderTopColor = al.color;
    card.innerHTML = `
      <div class="person-top">
        <span>${al.icon} <strong>${al.name}</strong></span>
        <span class="tier tier-${rec.tier === 'member' ? 'cold' : rec.tier === 'silver' ? 'warm' : 'hot'}">${rec.tier}</span>
      </div>
      <div class="flight-sub">${rec.miles.toLocaleString()} mi · ${rec.segments} segs · ${rec.points.toLocaleString()} pts${rec.lastActiveWeek != null ? ` · last flown Wk ${rec.lastActiveWeek}` : ''}</div>
      <div class="progress"><div class="progress-bar" style="width:${prog.pct}%; background:${al.color};"></div></div>
      <div class="flight-sub">${prog.next ? `Next: ${prog.next} — ${prog.needMiles.toLocaleString()} mi or ${prog.needSeg} segs` : 'Top tier ✨'}</div>`;
    loyaltyEl.appendChild(card);
  }
}

function render() {
  const weekNum = getWeek();
  if (!trip) trip = loadTrip();
  if (!trip) initTrip();
  renderCharBar();
  syncSetupSelects();
  const store = loyaltyStore();
  clockEl.textContent = `Week ${weekNum} · ${trip.airport} · ${formatGameTime(trip.gameTime, trip.airport)} (STD, no DST)`;
  const budget = budgetFor(trip.difficulty);
  walletEl.textContent = budget == null
    ? `💰 Unlimited budget · $${trip.spent.toLocaleString()} spent`
    : `💰 $${(budget - trip.spent).toLocaleString()} left of $${budget.toLocaleString()} (${DIFFICULTIES[trip.difficulty].label})`;
  walletEl.classList.toggle('over', budget != null && trip.spent > budget);
  scoreEl.textContent = `⭐ ${getScore()} pts this week`;
  renderPicker(); // keeps the interest lock note in sync after the first action
  if (arrivalMsg) {
    arrivalEl.style.display = '';
    arrivalEl.textContent = arrivalMsg;
  } else {
    arrivalEl.style.display = 'none';
  }
  renderFlights(weekNum, store);
  renderPeople(weekNum, store);
  renderIntel(weekNum);
  renderLoyalty(weekNum, store);
  renderProfile();
}

// Setup inputs mirror the live trip only when the week/character context
// changes — never while the player is editing them in Profile.
let selectsFor = '';
function syncSetupSelects() {
  const key = `${cid()}:w${getWeek()}`;
  if (selectsFor === key || !trip) return;
  selectsFor = key;
  weekInput.value = getWeek();
  airportInput.value = trip.airport;
  difficultyInput.value = trip.difficulty;
}

function renderProfile() {
  const c = activeChar();
  profileCharEl.innerHTML = '';
  if (c) {
    const d = document.createElement('div');
    d.className = 'profile-char-card';
    let since = '';
    try { since = c.createdAt ? new Date(c.createdAt).toLocaleDateString() : ''; } catch { /* ignore */ }
    d.innerHTML = `<span class="person-avatar">${c.avatar}</span><div><div class="person-name">${c.name}</div><div class="flight-sub">${since ? `Traveling since ${since} · ` : ''}${c.interests.length} permanent interests</div></div>`;
    profileCharEl.appendChild(d);
  }
  const budget = budgetFor(trip.difficulty);
  currentWeekEl.textContent = `Playing Week ${getWeek()} · started at ${trip.airport} · ${budget == null ? 'Unlimited budget' : `${DIFFICULTIES[trip.difficulty].label} budget ($${budget.toLocaleString()})`} · $${trip.spent.toLocaleString()} spent`;
}

function weekHasProgress() {
  if (getScore() > 0 || getMetIds().size > 0) return true;
  if (!trip) return false;
  return trip.spent > 0 || trip.gameTime > startTimeForAirport(trip.airport);
}

// Native confirm, guarded so headless/blocked environments default to "yes".
function safeConfirm(msg) {
  try {
    if (typeof confirm === 'function') return confirm(msg);
  } catch { /* ignore */ }
  return true;
}

// ---- encounter modal ----
function openEncounter(person, store) {
  encounterTarget = person;
  encounterPicked = new Set();
  renderEncounterPick(store);
  modalEl.style.display = 'flex';
}

function closeEncounter() {
  modalEl.style.display = 'none';
  encounterTarget = null;
}

function renderEncounterPick(store) {
  const p = encounterTarget;
  if (!p) return;
  const bonus = loungeBonus({ ...trip, loyalty: store.recs }, trip.airport);
  const mult = matchMultiplier(p.matchScore);
  const eligible = eligibleActivities(p);
  modalEl.innerHTML = `
    <div class="modal-card">
      <div class="person-top">
        <span class="person-avatar">${p.avatar}</span>
        <div><div class="person-name">${p.name}, ${p.age}</div>
        <div class="flight-sub">${p.background} · ${p.tier} · ×${mult.toFixed(1)} match mult${bonus > 0 ? ' · ✨ lounge +15%' : ''}</div></div>
        <span class="tier tier-${p.tier.toLowerCase()}">${p.tier}</span>
      </div>
      <div class="flight-sub">⏱ ${formatDuration(p.minutesLeft)} before their flight · pick up to ${MAX_ACTIVITIES} activities (saying hi costs 15m)</div>
      <div class="act-list">
        ${eligible.map((a) => {
          const chance = Math.round(successChance(a, p, bonus) * 100);
          const pts = Math.round(a.basePoints * mult);
          return `<button class="act-row" data-act="${a.name}">
            <span><strong>${a.name}</strong> · ${formatDuration(a.duration)} · ~${pts} pts</span>
            <span class="chance">${chance}%</span>
          </button>`;
        }).join('')}
      </div>
      ${eligible.length === 0 ? '<div class="flight-sub">No chemistry — nothing to try here.</div>' : ''}
      <div class="modal-actions">
        <button class="btn btn-small" id="enc-cancel">Not now</button>
        <button class="btn btn-primary btn-small" id="enc-go">Go (${encounterPicked.size})</button>
      </div>
    </div>`;
  modalEl.querySelectorAll('.act-row').forEach((b) => {
    const name = b.dataset.act;
    if (encounterPicked.has(name)) b.classList.add('picked');
    b.addEventListener('click', () => {
      if (encounterPicked.has(name)) encounterPicked.delete(name);
      else {
        if (encounterPicked.size >= MAX_ACTIVITIES) return;
        encounterPicked.add(name);
      }
      modalEl.querySelectorAll('.act-row').forEach((x) => x.classList.toggle('picked', encounterPicked.has(x.dataset.act)));
      modalEl.querySelector('#enc-go').textContent = `Go (${encounterPicked.size})`;
    });
  });
  modalEl.querySelector('#enc-cancel').addEventListener('click', closeEncounter);
  modalEl.querySelector('#enc-go').addEventListener('click', () => resolveEncounter(store));
  modalEl.onclick = (e) => { if (e.target === modalEl) closeEncounter(); };
}

function resolveEncounter(store) {
  const p = encounterTarget;
  if (!p) return;
  const bonus = loungeBonus({ ...trip, loyalty: store.recs }, trip.airport);
  const result = runEncounter(p, [...encounterPicked], Math.random, bonus);
  trip.gameTime += result.totalTime;
  lockWeek();
  saveTrip();
  markMet(p.id);
  const total = addScore(result.totalPoints);
  logEncounter({
    name: p.name, tier: p.tier, points: result.totalPoints,
    activities: result.results.map((r) => `${r.name}${r.success ? '' : ' (miss)'}`),
    minutes: result.totalTime, airport: trip.airport, lounge: result.loungeBoost,
  });
  modalEl.innerHTML = `
    <div class="modal-card">
      <div class="person-top">
        <span class="person-avatar">${p.avatar}</span>
        <div><div class="person-name">${p.name}</div>
        <div class="flight-sub">${formatDuration(result.totalTime)} spent · ×${result.multiplier} mult${result.trimmed ? ' · trimmed to fit their layover' : ''}${result.loungeBoost ? ' · ✨ lounge boost' : ''}</div></div>
      </div>
      <div class="act-list">
        ${result.results.length === 0 ? '<div class="flight-sub">Just said hi — no time for more before their flight.</div>' : ''}
        ${result.results.map((r) => `
          <div class="act-row done ${r.success ? 'win' : 'miss'}">
            <span>${r.success ? '✓' : '✗'} ${r.name}</span>
            <span>${r.success ? `+${r.points}` : '+0'}</span>
          </div>`).join('')}
      </div>
      ${result.consolation ? '<div class="flight-sub">No spark, but a nice chat (+5 consolation).</div>' : ''}
      <div class="reward">+${result.totalPoints} pts · ${total} total</div>
      <div class="modal-actions">
        <button class="btn btn-primary btn-small" id="enc-done">Continue</button>
      </div>
    </div>`;
  modalEl.querySelector('#enc-done').addEventListener('click', () => { closeEncounter(); render(); });
  modalEl.onclick = (e) => { if (e.target === modalEl) { closeEncounter(); render(); } };
}

document.getElementById('goto-week-btn').addEventListener('click', () => {
  const n = Math.max(1, parseInt(weekInput.value || '1', 10));
  if (n === getWeek()) { render(); return; }
  if (weekHasProgress() && !safeConfirm(`Leave Week ${getWeek()}? Its flights, score, and encounters stay saved for this traveler.`)) {
    weekInput.value = getWeek();
    return;
  }
  currentWeek = n;
  trip = null;
  arrivalMsg = '';
  erosionMsg = '';
  render();
});
document.getElementById('restart-week-btn').addEventListener('click', () => {
  if (weekHasProgress() && !safeConfirm(`Restart Week ${getWeek()}? This wipes its flights, score, and encounters for this traveler.`)) return;
  try {
    localStorage.removeItem(tripKey());
    localStorage.removeItem(scoreKey());
    localStorage.removeItem(metKey());
    localStorage.removeItem(logKey());
  } catch { /* ignore */ }
  arrivalMsg = '';
  erosionMsg = '';
  selectsFor = '';
  initTrip();
  render();
});
document.querySelectorAll('[data-advance]').forEach((b) => {
  b.addEventListener('click', () => {
    if (!trip) return;
    trip.gameTime += parseInt(b.dataset.advance, 10);
    lockWeek();
    arrivalMsg = '';
    saveTrip();
    render();
  });
});
document.querySelectorAll('.tab').forEach((b) => {
  b.addEventListener('click', () => {
    activeTab = b.dataset.tab;
    document.querySelectorAll('.tab').forEach((x) => x.classList.toggle('active', x === b));
    for (const t of ['flights', 'people', 'intel', 'miles', 'profile']) {
      document.getElementById(`tab-${t}`).style.display = activeTab === t ? '' : 'none';
    }
  });
});

try {
  const d = localStorage.getItem('ca_difficulty');
  if (d && DIFFICULTIES[d]) difficultyInput.value = d;
} catch { /* ignore */ }
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => navigator.serviceWorker.register('service-worker.js').catch(() => {}));
}
const _chars = ensureChars();
if (_chars.length === 0) openCharModal(true);
render();
